  const { accent, muted, stroke } = TONES[tone];

  return (
    <svg aria-hidden="true" className={className} viewBox="0 0 32 32">
      <polyline
        className={cn("fill-none", stroke)}
        points="8,24 16,16 24,8"
        strokeLinecap="round"
        strokeWidth={2.2}
      />
      {CENTRES.flatMap((cx, col) =>
        CENTRES.map((cy, row) => (
          <rect
            className={ACCENT_CELLS.has(`${col},${row}`) ? accent : muted}
            height={CELL}
            key={`${col},${row}`}
