import { Container, Eyebrow, SectionHeading } from "./container";
import { Mark } from "./mark";

const ROWS: readonly {
  fact: string;
  question: string;
  source: string;
}[] = [
  {
    fact: "A person on your team, by name, on a date you can read.",
    question: "Who vouched for it",
    source: "Nobody. It is what somebody said, verbatim.",
  },
  {
    fact: "Stated plainly, as something the company knows.",
    question: "How an answer may use it",
    source: "Quoted and attributed, always marked unreviewed.",
  },
  {
    fact: "Both facts are shown, and the disagreement is named.",
    question: "What happens on a conflict",
    source: "The confirmed fact wins — and the answer says the new material disagrees.",
  },
  {
    fact: "Superseded, with the date you stopped believing it kept apart from the date it stopped being true.",
    question: "What happens when it changes",
    source: "Nothing. It is a snapshot of a moment, and moments do not update.",
  },
];

export function Gate() {
  return (
    <section className="border-mn-rule/70 border-b py-20 sm:py-24" id="gate">
      <Container>
        <div className="grid gap-12 lg:grid-cols-[minmax(0,20rem)_minmax(0,1fr)] lg:gap-20">
          <div>
            <Eyebrow>The review gate</Eyebrow>
            <SectionHeading className="mt-5">
              Two tiers. Never blurred.
            </SectionHeading>
            <p className="mt-6 text-[1rem] text-mn-ink-soft leading-[1.7]">
              Everything your team captures is searchable straight away. Only
              what a human confirmed is treated as something the company knows.
              The assistant is built so it cannot quietly promote one into the
              other.
            </p>

            <figure className="mt-10 flex items-center gap-5">
              <Mark className="size-16 shrink-0" tone="stamp" />
              <figcaption className="text-[0.8125rem] text-mn-graphite leading-[1.6]">
                Nine cells. Six captured, three confirmed, one line drawn
                through them. That is the mark, and it is also the product.
              </figcaption>
            </figure>
          </div>

          <div>
            <div className="grid grid-cols-[minmax(0,1fr)_minmax(0,1fr)] gap-x-6 border-mn-ink border-b pb-3 sm:grid-cols-[9rem_minmax(0,1fr)_minmax(0,1fr)]">
              <span className="hidden sm:block" />
              <span className="inline-flex items-center gap-2 font-medium font-mono text-[0.6875rem] text-mn-stamp uppercase tracking-[0.16em]">
                <span aria-hidden="true" className="size-1.5 rounded-[1px] bg-mn-stamp" />
                Confirmed fact
              </span>
              <span className="inline-flex items-center gap-2 font-medium font-mono text-[0.6875rem] text-mn-ochre uppercase tracking-[0.16em]">
                <span
                  aria-hidden="true"
                  className="size-1.5 rounded-[1px] border border-mn-ochre"
                />
                Raw source
              </span>
            </div>

            <dl className="grid grid-cols-[minmax(0,1fr)_minmax(0,1fr)] gap-x-6 sm:grid-cols-[9rem_minmax(0,1fr)_minmax(0,1fr)]">
              {ROWS.map((row) => (
                <div className="contents" key={row.question}>
                  <dt className="col-span-2 border-mn-rule border-b pt-6 pb-2 font-medium font-mono text-[0.6875rem] text-mn-graphite uppercase tracking-[0.1em] sm:col-span-1 sm:border-b-0 sm:pb-6 sm:leading-[1.6]">
                    {row.question}
                  </dt>
                  <dd className="border-mn-rule border-b py-5 pr-4 text-[0.9375rem] text-mn-ink leading-[1.6]">
                    {row.fact}
                  </dd>
                  <dd className="border-mn-rule border-b py-5 text-[0.9375rem] text-mn-ink-soft leading-[1.6]">
                    {row.source}
                  </dd>
                </div>
              ))}
            </dl>
          </div>
        </div>
      </Container>
    </section>
  );
}

