@import "tailwindcss";
@import "@repo/design-system/styles/globals.css";

@theme inline {
  /* memorynine landing.
     The palette is the product's own semantics, not decoration: graphite is
     material nobody has reviewed, ochre is a raw source (quotable, unverified),
     stamp is a confirmed fact, ink is redaction. If a colour appears on the
     landing page it is because the knowledge base draws that same distinction. */
  --color-mn-paper: #e9e7e1;
  --color-mn-raised: #f6f5f1;
  --color-mn-rule: #cdcac2;
  --color-mn-ink: #14161a;
  --color-mn-ink-soft: #4b4f56;
  --color-mn-graphite: #7b7972;
  --color-mn-stamp: #20348f;
  --color-mn-stamp-tint: #dfe3f4;
  --color-mn-ochre: #8f5c0e;
  --color-mn-ochre-tint: #f1e4cc;

  /* Both loaded via CDN in the marketing layout: Cabinet Grotesk carries the
     display voice, Switzer the body copy. */
  --font-cabinet: "Cabinet Grotesk", "Switzer", system-ui, sans-serif;
  --font-switzer: "Switzer", system-ui, sans-serif;
}

/* JetBrains Mono (loaded via Google Fonts in the marketing layout) for labels,
   ids and timestamps. The design system sets --font-mono to Geist Mono for
   app-wide consistency; marketing uses a dedicated face. Scoped to the
   .font-switzer wrapper so it only affects the marketing route tree. */
.font-switzer .font-mono,
.font-switzer.font-mono {
  font-family:
    "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas,
    monospace;
}

/* The landing page is art-directed light in both themes: its colours carry
   product meaning (confirmed / raw / redacted) that a dark inversion would
   scramble. Pinning color-scheme keeps form controls and scrollbars light
   inside it even when the rest of the site follows a dark system theme. */
.mn-surface {
  color-scheme: light;
  background-color: var(--color-mn-paper);
  color: var(--color-mn-ink);
}

