  --color-mn-paper: #e9e7e1;
  --color-mn-raised: #f6f5f1;
  --color-mn-rule: #cdcac2;
  --color-mn-ink: #14161a;
  --color-mn-ink-soft: #4b4f56;
  --color-mn-graphite: #7b7972;
