cd /tmp && python3 - <<'PY'
import json, pathlib
d = json.load(open("out.json"))["wordmark"]

def num(v):
    return str(int(v)) if float(v).is_integer() else str(v)

header = '''/**
 * The memorynine wordmark, converted to outlines.
 *
 * "memorynine" set in Cabinet Grotesk Extrabold at -0.03em tracking — the same
 * face and tracking the landing page sets live (`--font-cabinet`, and the
 * `Wordmark` component). Outlines rather than a `<text>` element because
 * everything this feeds — email clients, rasterised PNGs, anything opened in a
 * design tool — has no webfont to load, and would otherwise fall back to a
 * system face and quietly change the logo.
 *
 * The path is normalised: it starts at 0,0 and the box below is the ink bounds
 * rather than the em box, so a lockup can align to what you can actually see.
 * Coordinates are in font units, %(upem)s per em. BASELINE is where the baseline
 * sits inside the box, for setting the wordmark against anything typographic.
 *
 * Regenerating — only needed if the face or the tracking changes. The recipe is
 * in `brand/README.md`; the path below is committed so nothing at build time
 * reaches for a font CDN.
 */

/** Font units per em, matching the source face. */
export const WORDMARK_UPEM = %(upem)s;
/** Ink bounds — what the path actually covers, not the em box. */
export const WORDMARK_WIDTH = %(width)s;
export const WORDMARK_HEIGHT = %(height)s;
/** Distance from the top of the box down to the baseline. */
export const WORDMARK_BASELINE = %(baseline)s;

// Split at fixed offsets, not on whitespace: the separators inside path data
// are significant, so the chunks must concatenate back byte for byte.
export const WORDMARK_PATH =
''' % {k: num(v) for k, v in d.items() if k != "path"}

body = d["path"]
assert '"' not in body and "\\\\" not in body, "path would need escaping"
CHUNK = 88
chunks = [body[i:i + CHUNK] for i in range(0, len(body), CHUNK)]
lit = "\n".join('  "%s" +' % c for c in chunks)
lit = lit[: -2] + ";"

footer = '''

interface WordmarkOptions {
  /** Ink colour. The wordmark is monochrome by design. */
  ink: string;
}

export const wordmarkSvg = ({ ink }: WordmarkOptions): string =>
  [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${WORDMARK_WIDTH} ${WORDMARK_HEIGHT}" width="${WORDMARK_WIDTH}" height="${WORDMARK_HEIGHT}">`,
    `<path d="${WORDMARK_PATH}" fill="${ink}"/>`,
    "</svg>",
  ].join("");
'''

out = header + lit + footer
pathlib.Path("wordmark.ts").write_text(out)

# Verify the concatenation round-trips.
import re
rebuilt = "".join(re.findall(r'^  "(.*)" \+?;?$', lit, re.M))
assert rebuilt == body, (len(rebuilt), len(body))
print("round-trip ok,", len(body), "chars,", len(chunks), "chunks")
