      onClick={select}
      type="button"
    >
      <span
        aria-hidden="true"
        className={cn(
          "size-1.5 rounded-[1px]",
          isFact ? "bg-current" : "border border-current"
        )}
      />
      {citation.id}
      <span className="sr-only">
        {isFact
          ? " — confirmed fact, show its trace"
          : " — raw source, show its trace"}
      </span>
    </button>
  );
};

export function Trace() {
